import{_ as t,o,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Sequence Flow — Content Writing View","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-10-content-writting-view/sequence-flow.md","filePath":"feature/content-task-workflow/3-6-10-content-writting-view/sequence-flow.md"}'),s={name:"feature/content-task-workflow/3-6-10-content-writting-view/sequence-flow.md"};function r(d,e,c,i,l,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="sequence-flow-—-content-writing-view" tabindex="-1">Sequence Flow — Content Writing View <a class="header-anchor" href="#sequence-flow-—-content-writing-view" aria-label="Permalink to &quot;Sequence Flow — Content Writing View&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.6.10). <strong>Implemented</strong> — canvas-rendering editor with Yjs CRDT real-time sync over STOMP WebSocket (plan.md §6 direction B, not hand-written OT). Minimal <code>Task</code> entity only (not the full FR 3.6.1 scope). &gt; &gt; Updated 2026-10-01.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Creator A, Creator B</strong> — two users editing the same Task&#39;s content concurrently, each via <code>CanvasTextEditor</code> + <code>useTaskContentSync</code> in <code>brandhub-web-dashboard</code>.</li><li><strong>TaskController</strong> — <code>GET /api/v1/workspaces/{id}/tasks/{taskId}/content</code>, <code>@RequireRole({MANAGER, CREATOR})</code>.</li><li><strong>WsJwtHandshakeInterceptor</strong> — validates the JWT (query param <code>?token=</code>) at the WebSocket upgrade for <code>/ws/tasks</code>, reusing <code>JwtUtil.parseToken</code>.</li><li><strong>TaskContentWebSocketController</strong> — <code>@MessageMapping(&quot;/tasks/{taskId}/content&quot;)</code>, persists and broadcasts Yjs updates.</li><li><strong>TaskContentServiceImpl</strong> — <code>getContent</code>, <code>appendOperation</code>, <code>reportSnapshot</code>, <code>listVersions</code>, <code>restoreVersion</code>.</li><li><strong>Database</strong> — PostgreSQL <code>task_content_operations</code> (append-only, opaque base64 Yjs updates) and <code>task_content_snapshots</code>.</li></ul><h2 id="normal-flow-—-opening-content" tabindex="-1">Normal Flow — opening content <a class="header-anchor" href="#normal-flow-—-opening-content" aria-label="Permalink to &quot;Normal Flow — opening content&quot;">​</a></h2><ol><li>Creator A → Client A: opens <code>/workspaces/:id/content-writing</code>. If the URL has no <code>?taskId</code>, the page first creates a minimal draft Task via <code>POST /tasks</code> (dev-convenience — there is no Task list UI yet).</li><li>Client A → TaskController: <code>GET /tasks/{taskId}/content</code>.</li><li>TaskController → TaskContentServiceImpl: <code>findPostTaskOrThrow</code> — confirms the Task exists, belongs to the Workspace, and is type <code>POST</code>; <code>@RequireRole</code> confirms the caller is MANAGER or CREATOR.</li><li>TaskContentServiceImpl: loads the latest <code>TaskContentSnapshot</code> (if any) and every <code>TaskContentOperation</code> committed after it.</li><li>TaskController → Client A: <code>{ snapshot, operationsSinceSnapshot[], sequenceNumber }</code>.</li><li>Client A (<code>useTaskContentSync</code>): <code>Y.applyUpdate(yDoc, snapshot)</code> then replays each tail operation — reconstructs the shared <code>Y.Doc</code>.</li><li>Client A: opens a STOMP WebSocket to <code>/ws/tasks?token=&lt;JWT&gt;</code>.</li><li><code>WsJwtHandshakeInterceptor</code>: validates the token; on success, <code>PrincipalHandshakeHandler</code> (in <code>WebSocketConfig</code>) binds the resolved <code>AuthenticatedUser</code> to the STOMP session.</li><li>Client A: subscribes to <code>/topic/tasks/{taskId}/content</code>.</li><li>(In parallel) Creator B repeats steps 1-9 for the same Task.</li></ol><h2 id="normal-flow-—-real-time-editing-crdt-merge-not-ot-transform" tabindex="-1">Normal Flow — real-time editing (CRDT merge, not OT transform) <a class="header-anchor" href="#normal-flow-—-real-time-editing-crdt-merge-not-ot-transform" aria-label="Permalink to &quot;Normal Flow — real-time editing (CRDT merge, not OT transform)&quot;">​</a></h2><ol start="11"><li>Creator A types. The offscreen <code>contenteditable</code> captures the keystroke (composition-aware for Vietnamese IME).</li><li><code>CanvasTextEditor</code>: calls <code>yText.insert()</code>/<code>delete()</code> at the local caret — a local Yjs mutation. The canvas re-renders immediately (optimistic, no wait for the server).</li><li><code>useTaskContentSync</code>: the <code>Y.Doc</code> <code>update</code> event fires (origin not <code>&quot;remote&quot;</code>) → publishes to <code>/app/tasks/{taskId}/content</code> with <code>{ update: base64 }</code>.</li><li><code>TaskContentWebSocketController</code> → <code>TaskContentServiceImpl.appendOperation</code>: assigns the next <code>sequenceNumber</code> (<code>count(taskId) + 1</code>).</li><li>Persists the opaque base64 Yjs update into <code>task_content_operations</code> — the server never decodes it; Yjs itself is the CRDT/operation log.</li><li>Broadcasts <code>{ update, sequenceNumber, editedBy }</code> to every subscriber of <code>/topic/tasks/{taskId}/content</code>, including Client A itself (confirms the update&#39;s official <code>sequenceNumber</code>).</li><li>Client B receives the broadcast, applies <code>Y.applyUpdate(yDoc, update, &quot;remote&quot;)</code>. Yjs merges the concurrent edit automatically — no central transform step. The canvas re-renders the affected region.</li><li>Symmetric: when Creator B edits, steps 11-17 run identically with A and B swapped. Both <code>Y.Doc</code>s converge to the same state regardless of order (the CRDT convergence guarantee).</li></ol><h2 id="normal-flow-—-client-reported-snapshot" tabindex="-1">Normal Flow — client-reported snapshot <a class="header-anchor" href="#normal-flow-—-client-reported-snapshot" aria-label="Permalink to &quot;Normal Flow — client-reported snapshot&quot;">​</a></h2><ol start="19"><li>Once a client&#39;s <code>operationsSinceSnapshot</code> count crosses 200 (<code>useTaskContentSync</code>&#39;s <code>SNAPSHOT_THRESHOLD</code>), it posts <code>POST /tasks/{taskId}/content/snapshot</code> with <code>{ yjsState: base64(Y.encodeStateAsUpdate(yDoc)), atSequenceNumber }</code>.</li><li><code>TaskContentServiceImpl.reportSnapshot</code>: if a snapshot already exists at or beyond <code>atSequenceNumber</code> (e.g. another client reported first), skips — first reporter wins.</li><li>Otherwise inserts a new <code>task_content_snapshots</code> row.</li><li><code>TaskContentSnapshotJob</code> (server, <code>@Scheduled</code> every 5 minutes) cannot capture a snapshot itself — the server never decodes Yjs updates, so it has no merged state to save. It only logs which Tasks have crossed the threshold, as a signal that a connected client should report one soon.</li></ol><h2 id="normal-flow-—-version-history-restore" tabindex="-1">Normal Flow — version history / restore <a class="header-anchor" href="#normal-flow-—-version-history-restore" aria-label="Permalink to &quot;Normal Flow — version history / restore&quot;">​</a></h2><ol start="23"><li><code>VersionHistorySidebar</code> → <code>GET /tasks/{taskId}/content/versions</code> → lists <code>{ snapshotId, sequenceNumber, createdAt }</code>.</li><li>On Restore click → <code>POST /tasks/{taskId}/content/versions/{snapshotId}/restore</code>.</li><li><code>TaskContentServiceImpl.restoreVersion</code>: appends a <strong>new</strong> snapshot carrying the old <code>yjsState</code> at a fresh <code>sequenceNumber</code> — operations are append-only, so restoring doesn&#39;t rewind history, it adds a checkpoint that returns the document to that prior state.</li><li>Returns the restored content; the client reloads its <code>Y.Doc</code> from it.</li></ol><h2 id="error-paths" tabindex="-1">Error Paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error Paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP / WS</th><th>Error code</th></tr></thead><tbody><tr><td>Open content</td><td>Task does not exist, or belongs to a different Workspace</td><td>404</td><td><code>TASK_NOT_FOUND</code></td></tr><tr><td>Open content</td><td>Task is not of type <code>POST</code></td><td>400</td><td><code>INVALID_TASK_TYPE_FOR_CONTENT_WRITING</code></td></tr><tr><td>Open content</td><td>Caller is not MANAGER or CREATOR</td><td>403</td><td><code>FORBIDDEN</code> (<code>@RequireRole</code>)</td></tr><tr><td>WS handshake</td><td>Token missing or invalid</td><td>handshake rejected</td><td>401</td></tr><tr><td>Restore</td><td><code>snapshotId</code> not found or belongs to a different Task</td><td>404</td><td><code>TASK_NOT_FOUND</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>This is a minimal <code>Task</code> entity (FR 3.6.10 scope only) — not the full FR 3.6.1 Identify Task Detail (no assignee, due date, comments).</li><li><code>plan.md</code> originally sketched hand-defined <code>opType</code>/<code>position</code>/<code>payload</code> operations (direction A); the actual implementation stores raw Yjs updates instead (direction B) — Yjs&#39;s CRDT algorithm replaces the need for a hand-written <code>transform()</code> function. See <code>plan.md</code> §6 for the trade-off.</li><li>Out of scope in this pass (see <code>task.md</code>): accessibility shadow-DOM layer beyond the existing <code>aria-live</code> mirror, virtualization for multi-page documents, offline IndexedDB queue, font auto-conversion on publish.</li></ul>',16)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
